var a=[{title:`Cum funcționează rezistența`,text:`O ganteră cântărește la fel în orice punct, dar rezistența unei benzi depinde de cât este întinsă banda, de grosimea ei și de produsul respectiv. O bandă mai lungă sau mai groasă nu echivalează cu o greutate fixă, iar codurile de culori diferă între producători. Punctul din mișcare în care rezistența este cea mai mare poate fi, de asemenea, diferit față de un exercițiu cu greutăți libere.`},{title:`Opțiuni de exerciții`,text:`Benzile elastice merg bine pentru ramat, împingeri, ridicări laterale, împingeri Pallof și trageri la piept dintr-un punct de ancorare montat corect. O bandă în buclă în jurul genunchilor adaugă rezistență ușoară la exercițiile pentru șold. La unele mișcări poți călca pe bandă ca punct simplu de ancorare, atât timp cât nu poate aluneca și plesni în sus.`},{title:`Inspectează și ancorează în siguranță`,text:`Înainte de fiecare sesiune, caută crăpături, zone subțiate, rupturi, mânere deteriorate și conectori uzați. Folosește un punct de ancorare special, conform instrucțiunilor producătorului, și asigură-te că nu se poate desprinde. Nu întinde banda excesiv, nu o lăsa să se frece de muchii ascuțite și nu-ți pune fața în calea pe care ar plesni înapoi. O bandă care alunecă poate provoca leziuni la ochi și alte răni.`},{title:`Progresie și urmărire`,text:`Adaugă repetări controlate, treci la o bandă cu mai multă rezistență sau schimbă poziția picioarelor ori distanța față de punctul de ancorare, atât timp cât noua configurație rămâne sigură. Tensiunea se schimbă odată cu lungimea, așa că notează banda sau configurația folosită; culoarea ei nu îți va da o greutate precisă în kilograme. Nu crește brusc și tensiunea benzii, și amplitudinea în același timp.`},{title:`Folosirea TrainUp`,text:`În Profil, introdu rezistența benzilor pe care le ai. Socotește benzile drept disponibile doar când ai un punct de ancorare sigur pentru exercițiul pe care îl planifici. Dacă nu poți confirma punctul de ancorare, starea benzii sau spațiul tău, alege o alternativă mai sigură.`}];var r=[{label:`NHS: siguranța benzilor elastice de rezistență`,url:`https://abuhb.nhs.wales/files/patient-information-leaflets1/physiotherapy/safety-advice-when-exercising-with-resistance-bands-or-tubing-piu1332/`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:a,sources:r};export{n as default,a as sections,r as sources};